{
  "mechanisms": [
    {
      "name": "asymmetric_learning_rates",
      "title": "Asymmetric Learning Rates",
      "description": "Separate learning rates are used for positive and negative prediction errors.",
      "params": [
        {
          "name": "alpha_pos",
          "bounds": [0, 1]
        },
        {
          "name": "alpha_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "alpha_1 = alpha_pos if delta_stage1 > 0 else alpha_neg\nalpha_2 = alpha_pos if delta_stage2 > 0 else alpha_neg",
      "expressible_in_slots": true
    },
    {
      "name": "single_inverse_temperature",
      "title": "Single Inverse Temperature",
      "description": "A single inverse temperature parameter is used for both stage 1 and stage 2 choices.",
      "params": [
        {
          "name": "beta",
          "bounds": [0, 10]
        }
      ],
      "evidence": "logits_1 = beta * q_net + st * stickiness\n...\nlogits_2 = beta * q_stage2_mf[state_idx]",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_value_decay_to_center",
      "title": "Unchosen Value Decay to Center",
      "description": "Unchosen options decay towards a parameterized center value, which is also used to initialize the Q-values.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        },
        {
          "name": "center",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf = np.full(2, center, dtype=float)\nq_stage2_mf = np.full((2, 2), center, dtype=float)\n...\nunchosen_1 = 1 - a1\nq_stage1_mf[unchosen_1] = q_stage1_mf[unchosen_1] * (1 - decay) + center * decay\nfor s in range(2):\n    for a in range(2):\n        if not (s == state_idx and a == a2):\n            q_stage2_mf[s, a] = q_stage2_mf[s, a] * (1 - decay) + center * decay",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Stage 1 values are a weighted combination of model-based and model-free values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage 1 model-free values are updated by the stage 2 prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[a1] += alpha_1 * delta_stage1 + alpha_2 * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A stickiness parameter increases the probability of repeating the previous stage 1 action.",
      "params": [
        {
          "name": "st",
          "bounds": [0, 10]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\nif last_action != -1:\n    stickiness[last_action] = 1\nlogits_1 = beta * q_net + st * stickiness",
      "expressible_in_slots": true
    }
  ]
}
